const IMG = {'hero_img': 'data:image/jpeg;base64,', 'water_img': 'data:image/jpeg;base64,', 'cooled_img': 'data:image/jpeg;base64,', 'empty_img': 'data:image/jpeg;base64,', 'cold_img': 'data:image/jpeg;base64,', 'biscuits_img': 'data:image/jpeg;base64,', 'kharata_img': 'data:image/jpeg;base64,', 'mops_img': 'data:image/jpeg;base64,', 'wipers_img': 'data:image/jpeg;base64,', 'dishes_img': 'data:image/jpeg;base64,', 'sweets_img': 'data:image/jpeg;base64,', 'about_img': 'data:image/jpeg;base64,'};

const products = [
 {id:"water", title:"Mineral Water", sub:"1L | 500ml | 200ml", img:IMG.water_img, gallery:[["1L bottles",IMG.water_img],["500ml bottles",IMG.water_img],["200ml bottles",IMG.water_img]]},
 {id:"cooled", title:"Cooled Water Jars", sub:"For Drinking Water", img:IMG.cooled_img, gallery:[["Orange cooled jar",IMG.cooled_img],["Cooled water jar",IMG.cooled_img],["Drinking water jar",IMG.cooled_img]]},
 {id:"empty", title:"Empty Jars & Dispensers", sub:"20 Liters | 10 Liters", img:IMG.empty_img, gallery:[["20L jars",IMG.empty_img],["10L jar",IMG.empty_img],["Jar with dispenser",IMG.empty_img]]},
 {id:"cold", title:"Cold Drinks", sub:"All Leading Brands", img:IMG.cold_img, gallery:[["Cold Drinks",IMG.cold_img],["Soft Drinks",IMG.cold_img],["Beverage bottles",IMG.cold_img]]},
 {id:"biscuits", title:"Biscuits, Chocolates, Wafers & Chips", sub:"Britannia • Parle • Wafers • Chips", img:IMG.biscuits_img, gallery:[["Biscuits & snacks",IMG.biscuits_img],["Wafers & chips",IMG.biscuits_img],["Britannia & Parle",IMG.biscuits_img]]},
 {id:"kharata", title:"Kharata", sub:"Floor Brooms", img:IMG.kharata_img, gallery:[["Long twig broom",IMG.kharata_img],["Handled broom",IMG.kharata_img],["Floor broom styles",IMG.kharata_img]]},
 {id:"mops", title:"Mops", sub:"Cleaning", img:IMG.mops_img, gallery:[["Cotton mop",IMG.mops_img],["Floor-cleaning mop",IMG.mops_img]]},
 {id:"wipers", title:"Wipers", sub:"Floor & Glass", img:IMG.wipers_img, gallery:[["Floor wiper",IMG.wipers_img],["Glass/floor wiper",IMG.wipers_img]]},
 {id:"spare", title:"Spare Parts", sub:"Quality parts & accessories", img:SPARE_IMG, gallery:[["Spare parts",SPARE_IMG],["Metal components",SPARE_IMG],["Parts & accessories",SPARE_IMG]]},
 {id:"dishes", title:"Use & Throw Dishes", sub:"Plates • bowls • glasses • tea cups", img:IMG.dishes_img, gallery:[["Plates & bowls",IMG.dishes_img],["Glasses",IMG.dishes_img],["Tea cups",IMG.dishes_img]]}
];

const grid=document.getElementById("productGrid");
products.forEach(p=>{
  const card=document.createElement("article");
  card.className="product-card";
  card.innerHTML=`<div class="product-image"><img src="${p.img}" alt="${p.title}"></div>
  <div class="product-info"><h3>${p.title}</h3><p>${p.sub}</p><button class="arrow" aria-label="View ${p.title}">→</button></div>`;
  card.querySelector(".arrow").addEventListener("click",()=>openProduct(p));
  grid.appendChild(card);
});

document.getElementById("aboutImage").src=IMG.about_img;

const modal=document.getElementById("productModal");
const body=document.getElementById("modalBody");
function openProduct(p){
  body.innerHTML=`<h2>${p.title}</h2><p class="modal-sub">${p.sub}</p><div class="gallery">${
    p.gallery.map(g=>`<div class="gallery-item"><img src="${g[1]}" alt="${g[0]}"><b>${g[0]}</b></div>`).join("")
  }</div>`;
  modal.classList.add("open");
  modal.setAttribute("aria-hidden","false");
}
function closeProduct(){modal.classList.remove("open");modal.setAttribute("aria-hidden","true")}
document.querySelector(".close").addEventListener("click",closeProduct);
modal.addEventListener("click",e=>{if(e.target===modal)closeProduct()});
document.addEventListener("keydown",e=>{if(e.key==="Escape")closeProduct()});

document.querySelector(".menu").addEventListener("click",()=>{
  const nav=document.querySelector(".navlinks");
  nav.style.display=nav.style.display==="flex"?"none":"flex";
  if(nav.style.display==="flex"){nav.style.position="absolute";nav.style.top="64px";nav.style.right="0";nav.style.background="#fff";nav.style.padding="14px";nav.style.flexDirection="column";nav.style.alignItems="stretch";nav.style.boxShadow="0 8px 20px #0002"}
});
